// Serving an HTML page to people who aren't signed in (the /p/<id> route).
// Everything here is checked against Firestore and Storage's own rules by calling them as an anonymous visitor,
// so a page is only served if its owner marked it public.

const HTML_NAME = /\.(html|htm|xhtml|mhtml)$/i;

export const isHtmlName = (name: string) => HTML_NAME.test(name.trim());

/** File ids are generated by the app: lowercase letters and digits. Anything else is not ours. */
export const isFileId = (id: string) => /^[a-z0-9]{8,40}$/.test(id);

type FirestoreValue = { stringValue?: string; booleanValue?: boolean };

/** What the page needs from a document fetched through Firestore's REST API, or null if it isn't a servable public page. */
export function servablePage(doc: unknown): { path: string; name: string } | null {
  const fields = (doc as { fields?: Record<string, FirestoreValue> } | null)?.fields;
  if (!fields) return null;
  const path = fields.path?.stringValue;
  const name = fields.name?.stringValue;
  if (fields.public?.booleanValue !== true || !path || !name) return null;
  if (!isHtmlName(name) || !path.startsWith("files/") || path.includes("..")) return null;
  return { path, name };
}

/**
 * The page is shown from our own address, so it is sandboxed: it can run its scripts but gets an empty identity,
 * which means it can't read our cookies, storage or the signed-in session.
 */
export const PAGE_HEADERS: Record<string, string> = {
  "Content-Type": "text/html",
  "Content-Security-Policy": "sandbox allow-scripts allow-forms allow-popups allow-popups-to-escape-sandbox allow-downloads",
  "X-Content-Type-Options": "nosniff",
  "Referrer-Policy": "no-referrer",
  // Unlisted: reachable by link only, not by search engines. Short cache so turning sharing off takes effect quickly.
  "X-Robots-Tag": "noindex, nofollow",
  "Cache-Control": "public, max-age=60, s-maxage=60",
};

export const NOT_AVAILABLE_HTML =
  '<!doctype html><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Page not available</title>' +
  '<body style="font-family:system-ui,sans-serif;max-width:32rem;margin:15vh auto;padding:0 1rem;color:#1b1917"><h1 style="font-size:1.4rem">This page isn’t available</h1>' +
  "<p>The link may be wrong, the page may have been removed, or its owner may have turned sharing off.</p></body>";
